#include <GyverINA.h>             // Подключаемые библиотеки для корректной работы модуля
#include <GyverOLED.h>            // Они должны находиться в одной папке с файлом программы ArduinoIDE
#include <GyverButton.h>
#include <EEManager.h>
#include <GyverDS18.h>

//______________________________________________ПИНЫ________________________________________________________________________________
GButton up(3, HIGH_PULL);         // Кнопки UP, DOWN, OK
GButton down(4, HIGH_PULL);       // Цифра в скобках означает номер ЦИФРОВОГО пина на плате ардуино (D2, D3, D4)
GButton ok(2, HIGH_PULL);

uint8_t sensorPin = 3;            // АНАЛОГОВЫЙ пин для расчета напряжения датчика (цифра соответствует № АНАЛОГОВОГО пина. Например: 3 - это пин А3)
uint8_t batteryPin = 0;           // АНАЛОГОВЫЙ пин для расчета напряжения АКБ (цифра соответствует № АНАЛОГОВОГО пина. Например: 0 - это пин А0)
GyverDS18Single ds(5);            // ЦИФРОВОЙ пин датчика температуры (в данном случае D5)
//__________________________________________________________________________________________________________________________________

#define ITEMS 8                   // Общее кол-во пунктов меню на дисплее
#define END_LINE_X 31             // Начало координат стрелки
#define END_LINE_Y 31             // -//-

INA226 ina;                       // Модуль, который точно замеряет напряжение

GyverOLED<SSD1306_128x64, OLED_BUFFER> oled;            // oled дисплей
//GyverOLED<SSD1306_128x64, OLED_NO_BUFFER> oled;
//GyverOLED<SSD1306_128x64, OLED_BUFFER, OLED_SPI, 8, 7, 6> oled;

//__________________________________________________________________________________________________________________________________
//                                                                              $$
//                $$  $$     $$$$      $$$$     $$$$$$    $$$$$      $$$$     $$  $$    $$  $$    $$  $$
//                $$  $$    $$  $$    $$  $$      $$      $$  $$    $$  $$    $$  $$    $$ $$     $$  $$
//                $$$$$$    $$$$$$    $$          $$      $$$$$$    $$  $$    $$ $$$    $$$$      $$ $$$
//                $$  $$    $$  $$    $$  $$      $$      $$        $$  $$    $$$ $$    $$ $$     $$$ $$
//                $$  $$    $$  $$     $$$$       $$      $$         $$$$     $$  $$    $$  $$    $$  $$
//
//
//                   !!! ВО ВСЕХ ДРОБНЫХ ЧИСЛОВЫХ ЗНАЧЕНИЯХ ИСПОЛЬЗУЙТЕ ТОЧКУ(.)  А НЕ ЗАПЯТУЮ(,) !!!
//
#define VREF 4.96               // точное напряжение на пине 5V
#define R1 47000.0              // сопротивление резистора 1  // Рассчитывайте резисторы с запасом, даже чтобы при большем (чем обычно) напряжении акб
#define R2 23300.0              // сопротивление резистора 2  // на аналоговый пин не пошло напряжение более 5 вольт!!!
                                                              // К примеру я выбрал макс. напряжение акб = 15 вольт.
                                                              // Рассчитать можно здесь: https://cxem.net/calc/divider_calc.php
bool sensorType = 1;            // Тип датчика газа. 1 - трехконтактный (измерение напряжения). 0 - двухконтактный (измерение сопротивления)
char myName[] = "ХОЗЯИН";       // ваше имя, которое будет отображаться во время заставки при включении (писать в "кавычках"), но
                                // !!! НЕ БОЛЕЕ 10-И СИМВОЛОВ, ИНАЧЕ НЕ ПОМЕСТИТСЯ НА ДИСПЛЕЕ !!!
struct Data {
  float a = 1.66;            // минимальное напряжение на датчике - пустой бак (0.000 - 12.000 с шагом 0.001)
  float b = 3.70;            // максимальное напряжение на датчике - полный бак (0.000 - 12.000 с шагом 0.001)
  float c = 38;               // объем газового баллона в литрах (0 - 150 с шагом 0.5)
  float d = 16.5;             // средний расход газа на 100км (для расчета запаса хода) (0 - 25 с шагом 0.1)
  uint16_t e = 5000;          // частота опроса датчика напряжения в миллисекундах (5000 = один опрос в 5 сек) (0 - 65535)
  byte f = 10;                // яркость дисплея (0 - мин, 255 - макс). При значении 0 дисплей выключен!
  bool g = 1;                 // заставка при включении (1 - показывать, 0 - не показывать)
  byte h = 1;                 // вид отображения информации на дисплее. По умолчанию - 1. Меняется с самого устройства с помощью кнопки DOWN

  bool i = 0;                 // СБРОС ДО ЗАВОДСКИХ НАСТРОЕК. НИ В КОЕМ СЛУЧАЕ НЕ МЕНЯТЬ ЗДЕСЬ!!! ТОЛЬКО ЧЕРЕЗ МЕНЮ УСТРОЙСТВА!!!
};

bool distance = 1;            // флаг отображения оставшегося километража (1 - вкл, 0- выкл)
bool battery = 1;             // флаг отображения напряжения акб (1 - вкл, 0- выкл)
bool sensor = 1;              // флаг отображения напряжения с датчика уровня газа (1 - вкл, 0- выкл)
bool temp = 1;                // флаг отображения температуры (1 - вкл, 0- выкл)
bool level = 1;               // флаг отображения уровня газа в баке (1 - вкл, 0- выкл)
//__________________________________________________________________________________________________________________________________

Data data;                    // переменная структуры меню, с которой мы работаем в программе
EEManager memory(data);       // передаём нашу переменную (фактически её адрес)

//________________________________________________________________________________________________________

uint32_t timing = 0;          // Переменные для хранения точки отсчета таймера
uint32_t timing2 = 0;
uint32_t timing3 = 0;
uint32_t timing4 = 0;

bool flag = true;             // Флаг выбора в меню
bool flagMenu = true;         // Флаг меню/инфо
bool flagIcon = false;        // Флаг иконки газовой колонки

//____________________________МАССИВ ДАННЫХ ЗНАЧЕНИЙ ВОЛЬТАЖА ДАТЧИКА УРОВНЯ ГАЗА И ВОЛЬТАЖА АКБ__________
const int numReadings = 20;   // задаем размер массива датчика уровня газа
const int numReadBatt = 20;   // задаем размер массива вольтажа АКБ
float readings[numReadings];  // массив для хранения значений, полученных с INA226 
float readBatt[numReadBatt];  // массив для хранения значений вольтажа АКБ
int readIndex = 0;            // индекс последнего значения датчика уровня газа
int readIndexBatt = 0;        // индекс последнего значения вольтажа АКБ
float total = 0;              // сумма значений вольтажа с датчика уровня газа
float totalBatt = 0;          // сумма значений вольтажа АКБ
float average = 0;            // среднее значение вольтажа с датчика уровня газа
//________________________________________________________________________________________________________
float startLineX = 0;         // Координаты стрелки (стрелочный указатель уровня на дисплее)
float startLineY = 0;         // -//-
int levelLenght = 0;          // Процент заполненности бака газом
int startName = 0;            // Центровка на дисплее (заставка)
float batteryVoltage = 0;     // Напряжение на АКБ автомобиля
float Vout = 0;               // Переменная для хранения значения напряжения датчика уровня газа в средней точке делителя
float tempSensor;             // Переменная для хранения температуры
float battVoltage = 0;        // Переменная для хранения вольтажа АКБ
uint16_t battVoltDelay = 50;  // частота опроса напряжения АКБ в миллисекундах (50 = один опрос за 0,05 сек) (0 - 65535)
//________________________________________________________________________________________________________


void setup() {

  memory.begin(0, 'w');   // Сменить здесь букву 'w' на любую другую, если после первой прошивки Arduino не будут сохраняться изменения в меню устройства
                          // После смены буквы нужно заново прошить Arduino

  up.setDebounce(100);
  down.setDebounce(100);
  ok.setDebounce(100);
  up.setClickTimeout(250);
  down.setClickTimeout(250);

  ds.requestTemp();  // первый запрос на измерение

  oled.init();
  oled.setContrast(data.f);

    if (data.g == true) {
    viewScreensaver();
  }

  // Для повышения помехозащищенности INA226 имеет возможность настроить время выборки напряжения и тока
  // INA226 будет захватывать "кусок" сигнала выбранной продолжительности, что повысит точность на шумном сигнале
  // По умолчанию выборка занимает 1100 мкс, но может быть изменена методом .setSampleTime(канал, время);
  // Варианты времени выборки см. в таблице (файл INA226.h)

  ina.setSampleTime(INA226_VBUS, INA226_CONV_2116US);   // Время выборки напряжения
  ina.setSampleTime(INA226_VSHUNT, INA226_CONV_8244US); // Время выборки тока

  // Так же имеется возможность использовать встроенное усреднение выборок
  // Усреднение применяется и для напряжения и для тока и пропорционально увеличивает время оцифровки
  // Рекомендуется на шумной нагрузке, устанавливается методом .setAveraging(кол-во усреднений) (см. таблицу в INA226.h)

  ina.setAveraging(INA226_AVG_X4); // 4х кратное усреднение

  //________________________________________________________________________________________________________
  for (byte i = 0; i < numReadings; i++) {                    // заполняем массив значениями вольтажа с датчика уровня газа первый раз
    if (sensorType == 1) readings[i] = ina.getVoltage(), 3;   // если трехконтактный датчик
    else readings[i] = getVout(), 3;                          // если двухконтактный датчик
    total = total + readings[i];
  }

  for (byte i = 0; i < numReadBatt; i++) {                    // заполняем массив значениями вольтажа АКБ первый раз
    readBatt[i] = getBattVoltage(), 1;
    totalBatt = totalBatt + readBatt[i];
  }
  //________________________________________________________________________________________________________
}

void loop () {
  
  memory.tick();
  ok.tick();
  down.tick();
  up.tick();

  if (flagMenu) {                         // смена флага меняет вид: информация/меню   
    flag = true;
    display(); 
  }         
  else menu();

  if (ok.isHolded()) {                    // удержание кнопки ОК обновляет настройки в памяти
    flagMenu = !flagMenu;
    if(data.i) memory.reset();
    else memory.update();
  }

  if (flagMenu && down.isClick()) {       // нажатие кнопки DOWN на дисплее с информацией переключает вид дисплея
      if(data.h == 6) data.h = 1;
      else data.h += 1;
  }

  if (flagMenu && up.isClick()) {         // нажатие кнопки UP на дисплее с информацией переключает яркость дисплея (+25)
    if(data.f + 25 > 255) {
      data.f = 0;
      oled.setContrast(data.f);
    }
    else {
      data.f += 25;
      oled.setContrast(data.f);
    }
  }
}


void display() {

  oled.clear();
  average = averageVoltage();
  float literInBalloonOled = getLiterInBalloon(average, 3);

  //____________________________________________________________________________________________________________________
  oled.setScale(1);

  batteryVoltage = averageBatteryVoltage();
  switch (data.h) {
    case 1:
    if (battery) {
      oled.setCursorXY(0, 56);          // напряжение акб
      oled.print(batteryVoltage, 1);
      oled.setCursorXY(25, 56);
      oled.print(F("V"));
    }
    break;
    case 2:
    if (battery) {
      oled.rect(86, 17, 127, 30, OLED_FILL);
      oled.textMode(1);
      oled.setCursorXY(89, 20);
      oled.print(batteryVoltage, 1);
      oled.setCursorXY(120, 20);
      oled.print(F("V"));
      oled.textMode(0);
    } else oled.rect(86, 17, 127, 30, OLED_STROKE);
    break;
    case 6:
      oled.setScale(2);
      oled.setCursorXY(1, 43);
      oled.print(batteryVoltage, 1);
      oled.setScale(1);
      oled.setCursorXY(54, 50);
      oled.print(F("V"));
    break;
  }
  //____________________________________________________________________________________________________________________
  switch (data.h) {
    case 1:
    if (temp) {
      oled.setCursorXY(47, 56);         // температура
      oled.print(getTempDS(), 1);
      oled.setCursorXY(72, 56);
      oled.print(F("C"));
    }
    break;
    case 2:
    if (temp) {
      oled.rect(86, 49, 127, 62, OLED_FILL);
      oled.textMode(1);
      oled.setCursorXY(89, 52);
      oled.print(getTempDS(), 1);
      oled.circle(117, 53, 1, OLED_STROKE);
      oled.setCursorXY(120, 52);
      oled.print(F("C"));
      oled.textMode(0);
    } else oled.rect(86, 49, 127, 62, OLED_STROKE);
    break;
    case 6:
      oled.setScale(2);
      oled.setCursorXY(69, 43);
      oled.print(getTempDS(), 1);
      oled.setScale(1);
      oled.setCursorXY(120, 50);
      oled.print(F("C"));
    break;
  }
  //____________________________________________________________________________________________________________________
  switch (data.h) {
    case 1:
    if (sensor) {
      oled.setCursorXY(92, 56);
      if (sensorType == 1) oled.print(ina.getVoltage(), 3);      // значение вольтажа на датчике
      else oled.print(getVout(), 3); 
      oled.setCursorXY(123, 56);
      oled.print(F("V"));
    }
    break;
    case 2:
    if (sensor) {
      oled.rect(86, 33, 127, 46, OLED_FILL);
      oled.textMode(1);
      oled.setCursorXY(89, 36);
      if (sensorType == 1) oled.print(ina.getVoltage(), 3);
      else oled.print(getVout(), 3); 
      oled.setCursorXY(120, 36);
      oled.print(F("V"));
      oled.textMode(0);
    } else oled.rect(86, 33, 127, 46, OLED_STROKE);
    break;
  }
  //____________________________________________________________________________________________________________________
  switch (data.h) {
    case 1:
    if (level) {
      oled.rect(0, 47, 127, 52, OLED_STROKE);                                   // горизонтальный уровень
      levelLenght = (126.0 / 100) * ((literInBalloonOled / data.c) * 100);
      oled.rect(1, 48, levelLenght, 51, OLED_FILL);
    }
    break;
    case 2:
    if (level) {
      oled.rect(0, 55, 81, 62, OLED_STROKE);
      levelLenght = (80.0 / 100) * ((literInBalloonOled / data.c) * 100);
      oled.rect(1, 56, levelLenght, 61, OLED_FILL);
    }
    break;
  }
  //____________________________________________________________________________________________________________________
  oled.setScale(3);
  switch (data.h) {
    case 1:
      if (literInBalloonOled < 10.0) oled.setCursorXY(38, 16);          // значение литража
      else if (literInBalloonOled >= 20.0) oled.setCursorXY(29, 16);
      else oled.setCursorXY(28, 16);  
    break;
    case 2:
      if (literInBalloonOled < 10.0) oled.setCursorXY(15, 16);
      else if (literInBalloonOled >= 20.0) oled.setCursorXY(6, 16);
      else oled.setCursorXY(5, 16);
    break;
    case 3:
      oled.setScale(4);
      if (literInBalloonOled < 10.0) oled.setCursorXY(30, 17);
      else if (literInBalloonOled >= 20.0) oled.setCursorXY(17, 17);
      else oled.setCursorXY(16, 17);
    break;
    case 4:
      oled.setScale(3);
      if (literInBalloonOled < 10.0) oled.setCursorXY(58, 17);
      else if (literInBalloonOled >= 20.0) oled.setCursorXY(50, 17);
      else oled.setCursorXY(49, 17);
    break;
    case 6:
      oled.setScale(2);
      oled.setCursorXY(1, 6);
      oled.print(literInBalloonOled, 1);
      oled.setScale(1);
      oled.setCursorXY(54, 13);
      oled.print(F("L"));
    break;
  }

  if (data.h != 5 && data.h != 6) {
    oled.print(literInBalloonOled, 1);
  }
  //____________________________________________________________________________________________________________________
  if (literInBalloonOled <= 2.0) flagIcon = true;            // иконка газовой колонки
  else if (literInBalloonOled > 2.0 && literInBalloonOled < 5.0) {
    if (millis() - timing3 >= 1500) {
      timing3 = millis();
      flagIcon = !flagIcon;
    }
  }
  else flagIcon = false;

  switch (data.h) {
    case 1:
      if (flagIcon) gasStationIcon();
    break;
    case 2:
      if (flagIcon) gasStationIconMini(1, 0);
    break;
    case 4:
      if (flagIcon) gasStationIconMini(13, 25);
    break;
  }

  if (literInBalloonOled < 5.0 && data.h == 4) {      // Предупреждение "Пора заправиться"
    oled.setScale(1);
    oled.setCursorXY(49, 54);
    oled.print(F("заправиться!"));
    oled.setCursorXY(49, 45);
    oled.print(F("Пора"));
    oled.roundRect(42, 42, 124, 63, OLED_STROKE);
  }
  //____________________________________________________________________________________________________________________
  int kilometer = literInBalloonOled / data.d * 100;
  oled.setScale(1);

  switch (data.h) {
    case 1:
    if (distance) {
      if (kilometer < 10) oled.setCursorXY(123, 0);
      else if (kilometer >= 10 && kilometer < 100) oled.setCursorXY(117, 0);
      else oled.setCursorXY(111, 0);
      oled.print(kilometer);                // значение остатка в километрах
      oled.setCursorXY(117, 8);
      oled.print(F("км"));
    }
    break;
    case 2:
    if (distance) {
      oled.rect(86, 1, 127, 14, OLED_FILL);
      oled.textMode(1);
      oled.setCursorXY(89, 4);
      oled.print(kilometer);
      oled.setCursorXY(114, 4);
      oled.print(F("км"));
      oled.textMode(0);
    } else oled.rect(86, 1, 127, 14, OLED_STROKE);
    break;
    case 4:
      oled.setCursorXY(45, 0);
      oled.print(F("Остаток -"));
      oled.setCursorXY(108, 0);
      oled.print(kilometer);
    break;
    case 6:
      oled.setScale(2);
      oled.setCursorXY(69, 6);
      oled.print(kilometer);
      oled.setScale(1);
      oled.setCursorXY(115, 13);
      oled.print(F("KM"));
    break;
  }

  //____________________________________________________________________________________________________________________

  if (data.h == 4) {
    levelLenght = (100 / data.c) * literInBalloonOled;
    startLineX = END_LINE_X + sin(radians(360.0 - (1.8 * (100 - levelLenght)))) * 25.0;
    startLineY = END_LINE_Y - cos(radians(360.0 - (1.8 * (100 - levelLenght)))) * 25.0;
    oled.line(round(startLineX), round(startLineY), END_LINE_X, END_LINE_Y, OLED_FILL);

    oled.line(31, 0, 31, 2, OLED_FILL);
    oled.line(30, 0, 30, 1, OLED_FILL);
    oled.line(32, 0, 32, 1, OLED_FILL);

    oled.line(31, 60, 31, 62, OLED_FILL);                                    // СТРЕЛКА
    oled.line(30, 61, 30, 62, OLED_FILL);
    oled.line(32, 61, 32, 62, OLED_FILL);

    oled.line(0, 31, 2, 31, OLED_FILL);
    oled.line(0, 30, 1, 30, OLED_FILL);
    oled.line(0, 32, 1, 32, OLED_FILL);

    oled.circle(9, 9, 1, OLED_FILL);
    oled.circle(9, 53, 1, OLED_FILL);

    oled.circle(31, 31, 2, OLED_FILL);

    oled.dot(26, 1);
    oled.dot(21, 2);
    oled.dot(17, 3);
    oled.dot(13, 6);
    oled.dot(6, 13);
    oled.dot(3, 17);
    oled.dot(2, 21);
    oled.dot(0, 26);
    oled.dot(0, 36);
    oled.dot(2, 41);
    oled.dot(3, 45);
    oled.dot(6, 49);
    oled.dot(13, 56);
    oled.dot(17, 59);
    oled.dot(21, 60);
    oled.dot(26, 61);
  }
  //____________________________________________________________________________________________________________________

  if (data.h == 5) {
    int levelLenght = (100 / data.c) * literInBalloonOled;
    oled.rect(0, 0, 125, 52, OLED_STROKE);                                                    // БАТАРЕЙКА
    oled.rect(126, 17, 127, 35, OLED_FILL);

    if (levelLenght <= 2) oled.rect(4, 4, 13, 48, OLED_STROKE);
    else oled.rect(4, 4, 13, 48, OLED_FILL);

    if (levelLenght <= 10) oled.rect(16, 4, 25, 48, OLED_STROKE);
    else oled.rect(16, 4, 25, 48, OLED_FILL);

    if (levelLenght <= 20) oled.rect(28, 4, 37, 48, OLED_STROKE);
    else oled.rect(28, 4, 37, 48, OLED_FILL);

    if (levelLenght <= 30) oled.rect(40, 4, 49, 48, OLED_STROKE);
    else oled.rect(40, 4, 49, 48, OLED_FILL);

    if (levelLenght <= 40) oled.rect(52, 4, 61, 48, OLED_STROKE);
    else oled.rect(52, 4, 61, 48, OLED_FILL);

    if (levelLenght <= 50) oled.rect(64, 4, 73, 48, OLED_STROKE);
